const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);let W=0,H=0,dpr=1,last=0,mode='intro',time=0,shake=0,score=0,kills=0,spawned=0,player,enemies=[],particles=[],snow=[],camera=0,toastTimer=0;
const keys={};
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);snow=Array.from({length:Math.max(55,Math.floor(W/8))},()=>({x:Math.random()*W,y:Math.random()*H,z:.4+Math.random()*.9,s:.5+Math.random()*1.8}))}
new ResizeObserver(resize).observe(canvas);resize();
function start(){mode='playing';$('intro').classList.add('hidden');$('endScreen').classList.add('hidden');$('playerHealth').classList.remove('hidden');$('chapter').classList.remove('hidden');score=0;kills=0;spawned=0;camera=0;time=0;shake=0;player={x:150,y:0,hp:100,max:100,face:1,attack:0,cool:0,dodge:0,inv:0,combo:0,comboT:0,walk:0};enemies=[];particles=[];spawnWave(3);hud();last=performance.now();requestAnimationFrame(loop)}
function spawnWave(n){for(let i=0;i<n;i++){let boss=kills>=9&&i===0;enemies.push({x:player.x+W*(.55+Math.random()*.58)+i*35,hp:boss?190:45,max:boss?190:45,boss,face:-1,attack:0,cool:Math.random()+.5,stun:0,walk:Math.random()*7,alive:true,name:boss?'THE WARDEN':'DOCKSIDE THUG'})}spawned+=n}
function hud(){ $('healthNum').textContent=Math.max(0,Math.ceil(player.hp));$('healthBar').style.width=Math.max(0,player.hp)+'%';$('score').textContent=String(score).padStart(6,'0');$('waveLabel').textContent=kills>=9?'FINAL ENCOUNTER':'NIGHT ONE · '+String(kills).padStart(2,'0')+' / 10';let boss=enemies.find(e=>e.boss&&e.hp>0);$('enemyHealth').classList.toggle('hidden',!boss);if(boss){$('enemyName').textContent='THE WARDEN';$('enemyNum').textContent=Math.ceil(boss.hp);$('enemyBar').style.width=(boss.hp/boss.max*100)+'%'}}
function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=35+Math.random()*210;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-50,life:.25+Math.random()*.42,max:.65,color,size:2+Math.random()*3})}}
function announce(text){$('toast').textContent=text;$('toast').classList.add('show');toastTimer=.75}
function attack(kind){if(mode!=='playing'||player.cool>0||player.dodge>0)return;player.attack=kind==='kick'?.38:.28;player.cool=kind==='kick'?.55:.35;player.comboT=1.1;player.combo++;let range=kind==='kick'?105:78,hit=false;for(const e of enemies){if(e.hp<=0)continue;let dx=e.x-player.x;if(Math.abs(dx)<range&&Math.sign(dx||1)===player.face){let damage=kind==='kick'?31:20;if(player.combo>=3)damage+=8;e.hp-=damage;e.stun=kind==='kick'?.45:.3;e.x+=player.face*(kind==='kick'?42:22);hit=true;burst(e.x,H*.75-45,e.boss?'#f4af63':'#ff7161',kind==='kick'?12:7);if(e.hp<=0){score+=e.boss?5000:250;kills++;shake=e.boss?16:7;announce(e.boss?'CITY CLEARED':'NICE ONE');if(e.boss){victory()}else if(kills===9){spawnWave(1);announce('THE WARDEN IS HERE')}else if(kills<9&&enemies.filter(a=>a.hp>0).length<2)spawnWave(Math.min(3,10-kills-enemies.filter(a=>a.hp>0).length))}}}if(hit&&player.combo>=3)announce(['THREE-PIECE COMBO','HARD JUSTICE','COLD SNAP'][Math.floor(Math.random()*3)]);else if(!hit&&Math.random()<.22)announce(kind==='kick'?'WHIFF':'');if(kind==='kick')shake=Math.max(shake,2);hud()}
function victory(){mode='won';$('endEyebrow').textContent='THE CITY REMEMBERS';$('endTitle').innerHTML='NORTH<span style="color:#ed554c">STAR</span>'; $('endSub').textContent='HALIFAX IS STILL STANDING · SCORE '+String(score).padStart(6,'0');$('endScreen').classList.remove('hidden');$('playerHealth').classList.add('hidden');$('enemyHealth').classList.add('hidden')}
function fail(){mode='lost';$('endEyebrow').textContent='THE NIGHT TAKES ITS DUE';$('endTitle').innerHTML='NOT <span style="color:#ed554c">TONIGHT</span>'; $('endSub').textContent='THE CITY WILL WAIT FOR ANOTHER HERO';$('endScreen').classList.remove('hidden');$('playerHealth').classList.add('hidden');$('enemyHealth').classList.add('hidden')}
function dodge(){if(mode==='playing'&&player.cool<.12&&player.dodge<=0){player.dodge=.3;player.inv=.42;player.x+=player.face*55;burst(player.x,H*.75-6,'#d7e9ef',5)}}
function press(k){if(k==='left'||k==='a'||k==='arrowleft')keys.left=true;if(k==='right'||k==='d'||k==='arrowright')keys.right=true;if(k==='punch'||k==='j')attack('punch');if(k==='kick'||k==='k')attack('kick');if(k==='dodge'||k===' ')dodge()}
function release(k){if(k==='left'||k==='a'||k==='arrowleft')keys.left=false;if(k==='right'||k==='d'||k==='arrowright')keys.right=false}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();if(!keys[k])press(k);keys[k]=true;if(k==='enter'&&(mode==='intro'||mode==='won'||mode==='lost'))start()});window.addEventListener('keyup',e=>{let k=e.key.toLowerCase();keys[k]=false;release(k)});window.addEventListener('blur',()=>{keys.left=keys.right=false});
$('start').onclick=start;$('restart').onclick=start;
document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();press(k)});b.addEventListener('pointerup',()=>release(k));b.addEventListener('pointerleave',()=>release(k))});

