input.newString:
$('start').onclick=start;$('restart').onclick=start;
document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();press(k)});b.addEventListener('pointerup',()=>release(k));b.addEventListener('pointerleave',()=>release(k))});
function polygon(points,fill,stroke){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function background(){let horizon=H*.65,g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#14283b');g.addColorStop(.55,'#263847');g.addColorStop(1,'#192a35');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// distant moon and winter haze
let mx=W*.77-(camera*.055%W),my=H*.22;let glow=ctx.createRadialGradient(mx,my,5,mx,my,130);glow.addColorStop(0,'#e1e2d2bb');glow.addColorStop(.22,'#b4c5c944');glow.addColorStop(1,'#a9c7d000');ctx.fillStyle=glow;ctx.fillRect(mx-135,my-135,270,270);ctx.fillStyle='#e2e4d8';ctx.beginPath();ctx.arc(mx,my,22,0,Math.PI*2);ctx.fill();
// harbour haze
let hg=ctx.createLinearGradient(0,horizon-35,0,horizon+115);hg.addColorStop(0,'#d7c6ae00');hg.addColorStop(.4,'#c7c9bd22');hg.addColorStop(1,'#6b7b7a00');ctx.fillStyle=hg;ctx.fillRect(0,horizon-35,W,150);
let off=-(camera*.18%330);for(let i=-1;i<Math.ceil(W/240)+2;i++){let x=i*260+off,seed=(i+15)*19;let bw=120+((seed*37)%95),bh=130+((seed*23)%200),y=horizon-bh;ctx.fillStyle=['#172735','#1a2a38','#20313d','#182633'][Math.abs(i)%4];ctx.fillRect(x,y,bw,bh);ctx.fillStyle='#bbc5c316';ctx.fillRect(x+8,y+12,2,bh-14);let rows=Math.floor(bh/18);for(let r=1;r<rows;r++)for(let c=0;c<Math.floor(bw/15);c++){let lit=((c*13+r*7+i*5)%9===0);ctx.fillStyle=lit?'#e6bd77':'#a9bec515';ctx.fillRect(x+9+c*14,y+13+r*17,5,8)}if(i%3===0){ctx.fillStyle='#25333d';ctx.fillRect(x+bw*.24,y-16,bw*.52,18);}}
// distant harbour cranes
for(let i=0;i<2;i++){let x=(i*W*.55+W*.13-camera*.25%W);ctx.strokeStyle='#101e29aa';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x,horizon-20);ctx.lineTo(x,horizon-138);ctx.lineTo(x+95,horizon-138);ctx.lineTo(x+144,horizon-108);ctx.moveTo(x+20,horizon-139);ctx.lineTo(x+20,horizon-108);ctx.stroke();ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+92,horizon-135);ctx.lineTo(x+92,horizon-88);ctx.stroke()}
// road and boardwalk
ctx.fillStyle='#253038';ctx.fillRect(0,horizon,W,H-horizon);let ground=ctx.createLinearGradient(0,horizon,0,H);ground.addColorStop(0,'#394149');ground.addColorStop(1,'#111a22');ctx.fillStyle=ground;ctx.fillRect(0,horizon,W,H-horizon);ctx.strokeStyle='#a5adb033';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,horizon+32);ctx.lineTo(W,horizon+32);ctx.stroke();for(let x=-(camera*.75%150);x<W+150;x+=150){ctx.strokeStyle='#b8c2c21b';ctx.beginPath();ctx.moveTo(x,horizon+34);ctx.lineTo(x-24,H);ctx.stroke();ctx.fillStyle='#d2d6d31b';ctx.fillRect(x+45,horizon+72,25,2)}
// street lamps with warm pools
for(let i=-1;i<Math.ceil(W/330)+2;i++){let x=i*330-(camera*.82%330)+85;let gy=horizon+90;ctx.strokeStyle='#121c25';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x,gy);ctx.lineTo(x,gy-115);ctx.lineTo(x+30,gy-128);ctx.stroke();let lg=ctx.createRadialGradient(x+30,gy-126,2,x+30,gy-126,105);lg.addColorStop(0,'#f1bd6832');lg.addColorStop(1,'#f1bd6800');ctx.fillStyle=lg;ctx.fillRect(x-75,gy-230,210,210);ctx.fillStyle='#ffd38a';ctx.fillRect(x+26,gy-130,10,4)}
}
function drawFighter(x,base,face,isBoss,walk,attack,stun,inv){ctx.save();ctx.translate(x,base);ctx.scale(face||1,1);let bob=Math.sin(walk*9)*2, kick=attack>.18&&attack<.38;ctx.globalAlpha=inv>.02&&Math.floor(time*24)%2===0?.45:1;
// shadow
ctx.fillStyle='#070c11a6';ctx.beginPath();ctx.ellipse(0,1,isBoss?38:27,7,0,0,Math.PI*2);ctx.fill();ctx.translate(0,bob);
let jacket=isBoss?'#4b3546':'#233c4d', trim=isBoss?'#ca694e':'#bf4945', pants=isBoss?'#28242d':'#1a2831';
// legs
let step=Math.sin(walk*9)*6;polygon([[-12,-35],[-2,-34],[-4+step,-9],[-8+step,-4],[-23+step,-5],[-25,-10]],pants);polygon([[4,-35],[15,-37],[20-step,-12],[26-step,-5],[12-step,-3],[7,-9]],isBoss?'#32313a':'#202d35');
// boots
polygon([[-24+step,-10],[-8+step,-10],[-5+step,-3],[-30+step,-2]],'#0c151c','#66747a66');polygon([[8-step,-10],[22-step,-11],[31-step,-4],[10-step,-3]],'#0b141a','#66747a66');
// torso silhouette
polygon([[-15,-75],[11,-77],[19,-48],[13,-31],[-16,-32],[-21,-50]],jacket,'#b7c8ce44');polygon([[-16,-73],[-7,-69],[-10,-39],[-17,-36],[-22,-51]],trim);polygon([[4,-69],[12,-70],[17,-48],[12,-37],[4,-42]],'#75909a55');
// scarf
if(!isBoss){polygon([[-8,-75],[5,-74],[2,-64],[-10,-66]],'#c94a43');polygon([[0,-70],[8,-72],[17,-84],[13,-62],[4,-60]],'#b43a38')}
// shoulder and head
ctx.fillStyle=isBoss?'#614454':'#c98e6b';ctx.beginPath();ctx.ellipse(0,-85,isBoss?14:11,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=isBoss?'#24232b':'#342e2c';ctx.beginPath();ctx.arc(-1,-91,isBoss?14:12,Math.PI,Math.PI*2);ctx.fill();if(isBoss){ctx.fillStyle='#9f4f4c';ctx.fillRect(-13,-91,25,5)}else{ctx.fillStyle='#d7dfdc';ctx.fillRect(-12,-94,23,4);ctx.fillStyle='#1b2d3b';ctx.fillRect(-3,-96,6,6)}
// arms; punch arm thrusts to the right
let punching=attack>.07&&!kick;ctx.strokeStyle=jacket;ctx.lineCap='round';ctx.lineWidth=isBoss?14:12;ctx.beginPath();ctx.moveTo(-14,-69);ctx.lineTo(-22,-50+Math.sin(walk*8)*2);ctx.lineTo(-17,-44);ctx.stroke();ctx.beginPath();ctx.moveTo(12,-68);if(punching){ctx.lineTo(27,-60);ctx.lineTo(43,-57)}else if(kick){ctx.lineTo(21,-61);ctx.lineTo(25,-50)}else{ctx.lineTo(20,-51+Math.sin(walk*8+1)*3);ctx.lineTo(17,-42)}ctx.stroke();ctx.fillStyle=isBoss?'#9d7160':'#b77b5d';ctx.beginPath();ctx.arc(punching?43:(kick?25:17),punching?-57:(kick?-50:-42),7,0,Math.PI*2);ctx.fill();if(punching){ctx.strokeStyle='#f8d987aa';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(44,-57);ctx.lineTo(60,-57);ctx.stroke()}
// belt buckle
ctx.fillStyle='#c2a576';ctx.fillRect(-4,-40,8,4);ctx.restore()}

